// The bowls' textures, generated by code on the CPU (bowls.md 5.2; no third-party assets). Each is a pure function of
// fixed seeds, so the phase-B bake (ITextureBakeProvider, "Bowls/<name>") writes the same pixels the runtime makes now.
//   bronze      64 x 512 albedo strip (u around, v along the profile, the lip's crown at v = 0.5, 0.26 m of arc in all):
//               warm bell bronze outside, a darker patina inside, a 6 mm polished band under the outer lip, two engraved
//               rings 10 and 13 mm under it, the lip polished; alpha = smoothness (0.55 outside, 0.40 inside, 0.75 polished)
//   bronzeN     512 x 512 tangent-space normal map: overlapping hammer dimples 6-9 mm wide (elliptical in texture space so they
//               are round on the bowl), on both faces; the engraved rings as fine grooves. x in R and A, y in G, z in B.
//   wood        512 x 512 atlas: flat-sawn walnut grain (~1 mm per texel, alpha 0.5), the maroon cushion cloth with its
//               piping (alpha 0.14) and the puja's suede (alpha 0.2): one material for the stand, cushions and stick
// Nothing glows: no emission anywhere.
using UnityEngine;

namespace MusicRoom.Bowls
{
    public static class BowlsTextures
    {
        static uint s_rng;
        static float Rnd() { unchecked { s_rng = s_rng * 1664525u + 1013904223u; } return (s_rng >> 8) / 16777216f; }

        // a small periodic value noise (wraps in x with period px)
        static float Hash(int x, int y, int seed) { unchecked { uint h = (uint)(x * 374761393 + y * 668265263 + seed * 2246822519u); h = (h ^ (h >> 13)) * 1274126177u; return ((h ^ (h >> 16)) & 0xffffff) / 16777216f; } }
        static float Noise(float x, float y, int px, int seed)
        {
            int x0 = Mathf.FloorToInt(x), y0 = Mathf.FloorToInt(y); float fx = x - x0, fy = y - y0;
            fx = fx * fx * (3 - 2 * fx); fy = fy * fy * (3 - 2 * fy);
            int xa = ((x0 % px) + px) % px, xb = (xa + 1) % px;
            float a = Hash(xa, y0, seed), b = Hash(xb, y0, seed), c = Hash(xa, y0 + 1, seed), d = Hash(xb, y0 + 1, seed);
            return Mathf.Lerp(Mathf.Lerp(a, b, fx), Mathf.Lerp(c, d, fx), fy);
        }
        static float Fbm(float x, float y, int px, int seed, int oct = 4)
        {
            float s = 0, amp = 0.5f, norm = 0;
            for (int o = 0; o < oct; o++) { s += amp * Noise(x, y, px, seed + o * 17); norm += amp; x *= 2; y *= 2; px *= 2; amp *= 0.5f; }
            return s / norm;
        }

        static Color Hex(string h) { ColorUtility.TryParseHtmlString(h, out Color c); return c; }

        /// <summary>Distance below the lip's crown (m) of texture row v on the outer face (&gt; 0), or above it on the inner face (&lt; 0).</summary>
        static float FromLip(float v) => (0.5f - v) * BowlsGeometry.ProfileSpan;

        public static Texture2D Bronze()
        {
            const int W = 64, H = 512;
            var t = new Texture2D(W, H, TextureFormat.RGBA32, true, false) { name = "Bowls/bronze", wrapModeU = TextureWrapMode.Repeat, wrapModeV = TextureWrapMode.Clamp, anisoLevel = 4 };
            var px = new Color32[W * H];
            Color bronze = Hex("#9c7a45"), patina = Hex("#5e4a2c"), polish = Hex("#c9a467"), dark = Hex("#6b4f28");
            for (int y = 0; y < H; y++)
            {
                float v = (y + 0.5f) / H, d = FromLip(v) * 1000f;            // mm from the crown (outer +, inner -)
                for (int x = 0; x < W; x++)
                {
                    float u = (x + 0.5f) / W;
                    float mott = Fbm(u * 8, v * 30, 8, 3), streak = Fbm(u * 24, v * 4, 24, 11, 3);
                    Color c; float sm;
                    if (d >= 0)
                    {
                        c = Color.Lerp(bronze, dark, Mathf.Clamp01((mott - 0.45f) * 1.4f) * 0.55f);
                        c = Color.Lerp(c, bronze * 1.08f, Mathf.Clamp01(streak - 0.55f) * 0.6f);
                        sm = 0.55f - 0.08f * (mott - 0.5f);
                        if (d < 1.6f) { c = Color.Lerp(c, polish, 0.75f); sm = 0.72f; }                  // the lip's rounded crown
                        else if (d < 7.6f) { c = Color.Lerp(polish, bronze, 0.12f + 0.1f * mott); sm = 0.76f; }   // the polished band
                        float ring = Mathf.Min(Mathf.Abs(d - 10f), Mathf.Abs(d - 13f));
                        if (ring < 0.45f) { c = Color.Lerp(c, dark * 0.75f, 0.85f * (1 - ring / 0.45f)); sm = 0.35f; }   // engraved rings
                    }
                    else
                    {
                        float di = -d;
                        c = Color.Lerp(patina, dark, Mathf.Clamp01(mott - 0.4f) * 0.5f);
                        c = Color.Lerp(c, patina * 0.82f, Mathf.Clamp01(streak - 0.5f) * 0.5f);
                        sm = 0.40f;
                        if (di < 4f) { c = Color.Lerp(c, bronze, 0.6f * (1 - di / 4f)); sm = Mathf.Lerp(0.6f, 0.4f, di / 4f); }  // worn inner edge
                    }
                    c.a = sm;
                    px[y * W + x] = c;
                }
            }
            t.SetPixels32(px); t.Apply(true, false);
            return t;
        }

        public static Texture2D BronzeNormal()
        {
            const int W = 512, H = 512;
            // physical texel sizes: u around a 0.47 m rim (the middle bowl), v 0.26 m of profile arc
            const float du = 0.47f * 1000f / W, dv = BowlsGeometry.ProfileSpan * 1000f / H;   // mm per texel
            var h = new float[W * H];
            s_rng = 0xb0e1b0e1u;
            int n = 3400;
            for (int k = 0; k < n; k++)
            {
                float cx = Rnd() * W, cy = Rnd() * H, rmm = 3.0f + Rnd() * 1.6f, depth = 0.06f + Rnd() * 0.07f;   // mm
                float rx = rmm / du, ry = rmm / dv;
                int x0 = Mathf.FloorToInt(cx - rx), x1 = Mathf.CeilToInt(cx + rx), y0 = Mathf.Max(0, Mathf.FloorToInt(cy - ry)), y1 = Mathf.Min(H - 1, Mathf.CeilToInt(cy + ry));
                for (int y = y0; y <= y1; y++)
                    for (int x = x0; x <= x1; x++)
                    {
                        float qx = (x - cx) / rx, qy = (y - cy) / ry, q = qx * qx + qy * qy;
                        if (q >= 1) continue;
                        int xi = ((x % W) + W) % W;
                        float cap = depth * (1 - q);                    // a shallow spherical-cap dimple
                        int idx = y * W + xi;
                        h[idx] = Mathf.Min(h[idx], -cap);              // overlapping blows: the deeper mark wins, ridges between
                    }
            }
            // the engraved rings: fine grooves 10 and 13 mm under the lip on the outer face
            for (int y = 0; y < H; y++)
            {
                float d = FromLip((y + 0.5f) / H) * 1000f;
                float ring = Mathf.Min(Mathf.Abs(d - 10f), Mathf.Abs(d - 13f));
                float smooth = d >= 0 && d < 7.6f ? 0.25f : 1f;          // the polished band and lip are smoothed by use
                for (int x = 0; x < W; x++)
                {
                    h[y * W + x] *= smooth;
                    if (d > 0 && ring < 0.5f) h[y * W + x] -= 0.05f * (1 - ring / 0.5f);
                }
            }
            var t = new Texture2D(W, H, TextureFormat.RGBA32, true, true) { name = "Bowls/bronzeN", wrapModeU = TextureWrapMode.Repeat, wrapModeV = TextureWrapMode.Clamp, anisoLevel = 4 };
            var px = new Color32[W * H];
            for (int y = 0; y < H; y++)
                for (int x = 0; x < W; x++)
                {
                    float hl = h[y * W + (x + W - 1) % W], hr = h[y * W + (x + 1) % W];
                    float hd = h[Mathf.Max(0, y - 1) * W + x], hu = h[Mathf.Min(H - 1, y + 1) * W + x];
                    var nn = new Vector3(-(hr - hl) / (2 * du), -(hu - hd) / (2 * dv), 1f).normalized;
                    byte bx = (byte)Mathf.Clamp(Mathf.RoundToInt((nn.x * 0.5f + 0.5f) * 255f), 0, 255);
                    byte by = (byte)Mathf.Clamp(Mathf.RoundToInt((nn.y * 0.5f + 0.5f) * 255f), 0, 255);
                    byte bz = (byte)Mathf.Clamp(Mathf.RoundToInt((nn.z * 0.5f + 0.5f) * 255f), 0, 255);
                    px[y * W + x] = new Color32(bx, by, bz, bx);
                }
            t.SetPixels32(px); t.Apply(true, false);
            return t;
        }

        public static Texture2D Wood()
        {
            const int W = 512, H = 512;
            var t = new Texture2D(W, H, TextureFormat.RGBA32, true, false) { name = "Bowls/wood", wrapMode = TextureWrapMode.Repeat, anisoLevel = 4 };
            var px = new Color32[W * H];
            Color walnut = Hex("#5e3d27"), late = Hex("#3c2517"), early = Hex("#76503a"), suede = Hex("#8a6a4a");
            Color maroon = Hex("#5a1f24"), piping = Hex("#8a4a46");
            int sRow = Mathf.RoundToInt(BowlsGeometry.SuedeV0 * H), gRow = Mathf.RoundToInt((BowlsGeometry.GrainVMax + BowlsGeometry.FabricV0) * 0.5f * H);
            for (int y = 0; y < H; y++)
                for (int x = 0; x < W; x++)
                {
                    float u = (float)x / W, v = (float)y / H;
                    Color c; float sm;
                    if (y >= gRow && y < sRow)
                    {
                        // the cushion cloth: a fine weave, a lighter piping line at the tube's outer seam
                        float fv = Mathf.Clamp01((v - BowlsGeometry.FabricV0) / (BowlsGeometry.FabricV1 - BowlsGeometry.FabricV0));
                        float weave = ((x + y) % 2 == 0 ? 1.04f : 0.96f) * (((x >> 1) + (y >> 1)) % 2 == 0 ? 1.02f : 0.98f);
                        float nf = Fbm(u * 64f, v * 64f, 64, 91, 3);
                        c = maroon * (weave * (0.9f + 0.2f * nf));
                        float seam = Mathf.Min(fv, 1 - fv);
                        if (seam < 0.03f) c = Color.Lerp(c, piping * weave, 0.85f);
                        sm = 0.14f + 0.04f * nf;
                    }
                    else if (y < sRow)
                    {
                        // flat-sawn walnut at ~1 mm per texel: growth rings as straight, slightly wandering lines along u
                        // (every 4-9 mm), fine open pores stretched along the grain, a slow figure in the colour
                        float wander = (Fbm(u * 2f, v * 5f, 2, 41, 3) - 0.5f) * 0.9f + (Fbm(u * 7f, v * 11f, 7, 43, 2) - 0.5f) * 0.12f;
                        // irregular ring spacing (a slow frequency wander) and rings of uneven strength
                        float phase = v * 46f + wander + (Fbm(0.37f, v * 9f, 1, 47, 3) - 0.5f) * 3.5f;
                        float ring = phase % 1f; if (ring < 0) ring += 1f;
                        float strength = 0.35f + 0.65f * Hash(0, Mathf.FloorToInt(phase), 49);
                        float lateW = strength * Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((ring - 0.66f) / 0.14f)) * (1f - Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((ring - 0.88f) / 0.1f)));
                        float pores = Fbm(u * 6f, v * 340f, 6, 53, 2);
                        float figure = Fbm(u * 1.5f, v * 3f, 2, 67, 3);
                        c = Color.Lerp(early, walnut, 0.55f + (figure - 0.5f) * 0.6f);
                        c = Color.Lerp(c, late, lateW * 0.45f);
                        c = Color.Lerp(c, late * 0.9f, Mathf.Clamp01((pores - 0.62f) * 4f) * 0.35f);
                        sm = 0.5f - lateW * 0.05f - Mathf.Clamp01((pores - 0.62f) * 4f) * 0.08f;
                    }
                    else
                    {
                        float n = Fbm(u * 120, v * 120, 120, 79, 3);
                        c = Color.Lerp(suede * 0.86f, suede * 1.08f, n);
                        sm = 0.18f + 0.04f * n;
                    }
                    c.a = sm;
                    px[y * W + x] = c;
                }
            t.SetPixels32(px); t.Apply(true, false);
            return t;
        }
    }
}
